[{"order":1,"type":"heading","text":"Headless UI and Radix UI Integration Patterns in Tailwind CSS"},{"order":2,"type":"paragraph","text":"Building modern, accessible design systems often requires combining the unstyled primitives of Headless UI or Radix UI with the utility-first styling power of Tailwind CSS. This tutorial explores advanced integration patterns to build robust component libraries."},{"order":3,"type":"heading","text":"Understanding Unstyled Primitives"},{"order":4,"type":"paragraph","text":"Headless UI and Radix UI provide accessible, unstyled UI components that handle complex keyboard navigation, focus trapping, and ARIA attributes out of the box. Tailwind CSS is then applied to provide the visual layer."},{"order":5,"type":"subheading","text":"Core Integration Principles"},{"order":6,"type":"bullet_point","text":"Separation of concerns: Primitives handle behavior and accessibility; Tailwind handles layout and styling."},{"order":7,"type":"bullet_point","text":"State-driven styling: Utilize data attributes (like data-state="open") provided by Radix UI to conditionally apply Tailwind classes."},{"order":8,"type":"bullet_point","text":"Composition: Wrap primitive components to create reusable design system tokens."},{"order":9,"type":"heading","text":"Radix UI Modal Implementation Example"},{"order":10,"type":"paragraph","text":"Below is an example of integrating Radix UI Dialog primitives with Tailwind CSS, utilizing data attributes for smooth open and close animations."},{"order":11,"type":"code","text":"import * as Dialog from "@radix-ui/react-dialog";

export function CustomModal() {
  return (
    <Dialog.Root>
      <Dialog.Trigger className="rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700">
        Open Dialog
      </Dialog.Trigger>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 bg-black/50 data-[state=open]:animate-fadeIn" />
        <Dialog.Content className="fixed left-1/2 top-1/2 w-full max-w-md -translate-x-1/2 -translate-y-1/2 rounded-lg bg-white p-6 shadow-xl">
          <Dialog.Title className="text-lg font-bold text-gray-900">Modal Title</Dialog.Title>
          <Dialog.Description className="mt-2 text-sm text-gray-650">
            This is an accessible modal styled entirely with Tailwind CSS.
          </Dialog.Description>
          <Dialog.Close className="mt-4 rounded bg-gray-200 px-3 py-1.5 text-sm text-gray-800 hover:bg-gray-300">
            Close
          </Dialog.Close>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}"},{"order":12,"type":"heading","text":"Headless UI Popover Integration"},{"order":13,"type":"paragraph","text":"Headless UI uses render props and React states instead of data attributes for managing open and closed UI states. Here is how you can style a Headless UI Popover."},{"order":14,"type":"code","text":"import { Popover } from "@headlessui/react";

export function CustomPopover() {
  return (
    <Popover className="relative">
      {({ open }) => (
        <>
          <Popover.Button className="rounded bg-indigo-600 px-4 py-2 text-white">
            Solutions
          </Popover.Button>
          <Popover.Panel className="absolute z-10 mt-3 w-60 rounded-xl bg-white p-4 shadow-lg ring-1 ring-black/5">
            <div className="flex flex-col gap-2">
              <a href="#" className="text-sm text-gray-700 hover:text-indigo-600">Analytics</a>
              <a href="#" className="text-sm text-gray-700 hover:text-indigo-600">Engagement</a>
            </div>
          </Popover.Panel>
        </>
      )}
    </Popover>
  );
}"},{"order":15,"type":"heading","text":"Best Practices for Maintenance"},{"order":16,"type":"bullet_point","text":"Extract common primitive wrappers into dedicated component files to avoid repeating Tailwind utility strings."},{"order":17,"type":"bullet_point","text":"Use libraries like clsx or tailwind-merge to cleanly combine default primitive styles with consumer-passed class names."}]
